<?php
require_once __DIR__.'/../includes/bootstrap.php';
require_role('commercial_manager');
$user=current_user();$flashes=render_flashes();
require_once __DIR__.'/_helpers.php';
$conn=Database::getConnection();
$managerId=(int)($user['id']??$user['user_id']??0);
if($managerId<1){http_response_code(403);exit('Invalid Commercial Manager account.');}
$currentPage='proposals';$pageTitle='Proposals & Quotations';
function pq_e($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function pq_date(string $v,bool $optional=false):bool{if($optional&&$v==='')return true;$d=DateTime::createFromFormat('Y-m-d',$v);return $d&&$d->format('Y-m-d')===$v;}
function pq_money($v,$currency='ZAR'):string{return ($currency==='ZAR'?'R ':$currency.' ').number_format((float)$v,2);}
function pq_owned(mysqli $db,int $id,int $uid):bool{$s=$db->prepare('SELECT id FROM commercial_proposals WHERE id=? AND commercial_manager_id=?');$s->bind_param('ii',$id,$uid);$s->execute();$ok=(bool)$s->get_result()->fetch_assoc();$s->close();return $ok;}
function pq_go(?int $id=null):never{header('Location: '.url('commercial_manager/proposals.php'.($id?'?proposal='.$id:'')));exit;}
$tables=['commercial_proposals','commercial_proposal_items','commercial_proposal_history'];$missing=[];foreach($tables as $t)if(!cm_table($conn,$t))$missing[]=$t;
if($missing){require __DIR__.'/_layout_start.php';?>
<div class="pq-head"><div><span>Sales &amp; Proposals</span><h2>Commercial Proposals &amp; Quotations</h2><p>Prepare pricing, submit proposals and track negotiations and client decisions.</p></div></div>
<div class="cm-alert cm-alert--warning"><i class="fas fa-database"></i><div>Proposal tables are not installed. Import <strong>commercial_proposal_management_migration.sql</strong> and reload this page.</div></div>
<?php require __DIR__.'/_layout_end.php';exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 cm_verify_csrf();$action=(string)($_POST['action']??'');$id=max(0,(int)($_POST['proposal_id']??0));
 try{
  if($action==='create'){
   $client=trim((string)($_POST['client_name']??''));$title=trim((string)($_POST['title']??''));$currency=(string)($_POST['currency']??'ZAR');$valid=trim((string)($_POST['valid_until']??''));$notes=trim((string)($_POST['notes']??''));
   if($client===''||$title===''||!in_array($currency,['ZAR','USD','EUR','GBP'],true)||!pq_date($valid,true))throw new RuntimeException('Enter a client, proposal title, valid currency and validity date.');
   $ref='PROP-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));
   $s=$conn->prepare("INSERT INTO commercial_proposals(commercial_manager_id,proposal_ref,client_id,client_name,title,currency,status,valid_until,notes) VALUES(?,?,?,?,?,?,'draft',NULLIF(?,''),?)");
   $clientId=max(0,(int)($_POST['client_id']??0));$s->bind_param('isisssss',$managerId,$ref,$clientId,$client,$title,$currency,$valid,$notes);
   if(!$s->execute())throw new RuntimeException('Proposal could not be created.');$id=(int)$s->insert_id;$s->close();
   cm_activity($conn,$managerId,'proposal_created','Created proposal '.$ref,'proposal',$id);
   cm_flash('success','Proposal draft created. Add pricing line items below.');pq_go($id);
  }
  if($id<1||!pq_owned($conn,$id,$managerId))throw new RuntimeException('Proposal not found or access denied.');
  if($action==='add_item'){
   $desc=trim((string)($_POST['item_description']??''));$qty=(float)($_POST['quantity']??0);$unit=round((float)($_POST['unit_price']??0),2);$tax=max(0,min(100,(float)($_POST['tax_rate']??0)));
   if($desc===''||$qty<=0||$unit<0)throw new RuntimeException('Enter a description, positive quantity and non-negative unit price.');
   $s=$conn->prepare('INSERT INTO commercial_proposal_items(proposal_id,item_description,quantity,unit_price,tax_rate) VALUES(?,?,?,?,?)');$s->bind_param('isddd',$id,$desc,$qty,$unit,$tax);
   if(!$s->execute())throw new RuntimeException('Pricing line could not be saved.');$itemId=(int)$s->insert_id;$s->close();
   $s=$conn->prepare("INSERT INTO commercial_proposal_history(proposal_id,commercial_manager_id,event_type,details) VALUES(?,?,'pricing_updated',?)");$d='Added pricing line: '.$desc;$s->bind_param('iis',$id,$managerId,$d);$s->execute();$s->close();
   cm_activity($conn,$managerId,'proposal_pricing_updated',$d,'proposal',$id);cm_flash('success','Pricing line added.');
  }elseif($action==='update_status'){
   $status=(string)($_POST['status']??'draft');$decision=(string)($_POST['client_decision']??'pending');$note=trim((string)($_POST['decision_notes']??''));
   if(!in_array($status,['draft','internal_review','submitted','negotiation','accepted','rejected','withdrawn','expired'],true)||!in_array($decision,['pending','accepted','rejected','changes_requested','no_response'],true))throw new RuntimeException('Invalid proposal status or client decision.');
   $s=$conn->prepare('UPDATE commercial_proposals SET status=?,client_decision=?,decision_notes=? WHERE id=? AND commercial_manager_id=?');$s->bind_param('sssii',$status,$decision,$note,$id,$managerId);
   if(!$s->execute())throw new RuntimeException('Proposal status update failed.');$s->close();
   $s=$conn->prepare('INSERT INTO commercial_proposal_history(proposal_id,commercial_manager_id,event_type,details) VALUES(?,?,?,?)');$event='status_'.$status;$details='Status: '.$status.'; client decision: '.$decision.'. '.$note;$s->bind_param('iiss',$id,$managerId,$event,$details);$s->execute();$s->close();
   cm_activity($conn,$managerId,'proposal_status_updated',$details,'proposal',$id);cm_flash('success','Proposal status updated.');
  }elseif($action==='update_details'){
   $valid=trim((string)($_POST['valid_until']??''));$notes=trim((string)($_POST['notes']??''));if(!pq_date($valid,true))throw new RuntimeException('Invalid validity date.');
   $s=$conn->prepare("UPDATE commercial_proposals SET valid_until=NULLIF(?,''),notes=? WHERE id=? AND commercial_manager_id=?");$s->bind_param('ssii',$valid,$notes,$id,$managerId);$s->execute();$s->close();cm_flash('success','Proposal details updated.');
  }else throw new RuntimeException('Unsupported proposal action.');
  pq_go($id);
 }catch(Throwable $e){cm_flash('error',$e->getMessage());pq_go($id?:null);}
}
$selectedId=max(0,(int)($_GET['proposal']??0));$selected=null;$items=[];$history=[];
if($selectedId&&pq_owned($conn,$selectedId,$managerId)){
 $s=$conn->prepare('SELECT * FROM commercial_proposals WHERE id=? AND commercial_manager_id=?');$s->bind_param('ii',$selectedId,$managerId);$s->execute();$selected=$s->get_result()->fetch_assoc();$s->close();
 if($selected){$s=$conn->prepare('SELECT * FROM commercial_proposal_items WHERE proposal_id=? ORDER BY id');$s->bind_param('i',$selectedId);$s->execute();$items=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$s=$conn->prepare('SELECT * FROM commercial_proposal_history WHERE proposal_id=? ORDER BY created_at DESC,id DESC LIMIT 20');$s->bind_param('i',$selectedId);$s->execute();$history=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}
}
$sql="SELECT p.*,COALESCE((SELECT SUM(i.quantity*i.unit_price) FROM commercial_proposal_items i WHERE i.proposal_id=p.id),0) subtotal,COALESCE((SELECT SUM(i.quantity*i.unit_price*i.tax_rate/100) FROM commercial_proposal_items i WHERE i.proposal_id=p.id),0) tax_total FROM commercial_proposals p WHERE p.commercial_manager_id=? ORDER BY p.created_at DESC";
$s=$conn->prepare($sql);$s->bind_param('i',$managerId);$s->execute();$proposals=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
$stats=['count'=>count($proposals),'submitted'=>0,'accepted'=>0,'pipeline'=>0.0];foreach($proposals as $p){if(in_array($p['status'],['submitted','negotiation'],true))$stats['submitted']++;if($p['status']==='accepted')$stats['accepted']++;if(!in_array($p['status'],['rejected','withdrawn','expired'],true)&&$p['currency']==='ZAR')$stats['pipeline']+=(float)$p['subtotal']+(float)$p['tax_total'];}
$subtotal=0;$taxTotal=0;foreach($items as $i){$line=(float)$i['quantity']*(float)$i['unit_price'];$subtotal+=$line;$taxTotal+=$line*(float)$i['tax_rate']/100;}$grand=$subtotal+$taxTotal;
require __DIR__.'/_layout_start.php';
?>
